//! Finite long-qualified receiver expectations frozen before source implementation or runtime.
use ktlsp_parser::{FileKind, Parsed, Parser, ParserError, SourceSnapshot};
use serde_json::{Value, json};
use std::sync::atomic::AtomicBool;

fn declaration(kind: &str) -> bool {
    matches!(
        kind,
        "CLASS" | "OBJECT_DECLARATION" | "FUN" | "PROPERTY" | "TYPEALIAS"
    )
}

fn projection(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                !e.token
                    && (declaration(&e.kind)
                        || matches!(
                            e.kind.as_str(),
                            "TYPE_PARAMETER_LIST"
                                | "TYPE_PARAMETER"
                                | "TYPE_REFERENCE"
                                | "NULLABLE_TYPE"
                                | "USER_TYPE"
                                | "DYNAMIC_TYPE"
                                | "REFERENCE_EXPRESSION"
                                | "VALUE_PARAMETER_LIST"
                                | "VALUE_PARAMETER"
                                | "TYPE_ARGUMENT_LIST"
                                | "TYPE_PROJECTION"
                                | "ANNOTATION_ENTRY"
                                | "PROPERTY_ACCESSOR"
                        ))
            })
            .map(|e| {
                let mut parent = e.parent;
                let owner = loop {
                    match parent {
                        Some(id) if declaration(&elements[id].kind) => {
                            break Some((elements[id].start, elements[id].end));
                        }
                        Some(id) => parent = elements[id].parent,
                        None => break None,
                    }
                };
                json!([
                    e.kind,
                    e.start,
                    e.end,
                    elements[e.parent.unwrap()].kind,
                    owner
                ])
            })
            .collect(),
    )
}

fn names(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                e.token
                    && e.kind == "IDENTIFIER"
                    && e.parent.is_some_and(|p| declaration(&elements[p].kind))
            })
            .map(|e| {
                json!([
                    elements[e.parent.unwrap()].start,
                    e.start,
                    e.end,
                    &tree.source()[e.start..e.end]
                ])
            })
            .collect(),
    )
}

fn diagnostics(tree: &Parsed) -> Value {
    Value::Array(
        tree.diagnostics()
            .iter()
            .map(|d| json!([d.start, d.end, d.message]))
            .collect(),
    )
}

fn positive(tree: &Parsed, case: &Value) {
    let id = case["id"].as_str().unwrap();
    assert_eq!(projection(tree), case["projection"], "{id}");
    assert_eq!(names(tree), case["declaration_names"], "{id}");
    assert_eq!(diagnostics(tree), case["diagnostics"], "{id}");
    for expected in case["receiver_tokens"].as_array().unwrap() {
        let start = expected[0].as_u64().unwrap() as usize;
        let end = expected[1].as_u64().unwrap() as usize;
        assert!(
            tree.elements().iter().any(|e| e.token
                && (e.start, e.end) == (start, end)
                && e.kind == expected[2].as_str().unwrap()
                && &tree.source()[start..end] == expected[3].as_str().unwrap()
                && e.parent
                    .is_some_and(|p| tree.elements()[p].kind == expected[4].as_str().unwrap())),
            "{id}"
        );
    }
    for (offset, expected) in case["positions"].as_object().unwrap() {
        let offset = offset.parse::<usize>().unwrap();
        if expected.as_str() == Some("INVALID_CRLF_MIDPOINT") {
            assert!(tree.position(offset).is_err(), "{id}: {offset}");
        } else {
            let actual = tree.position(offset).unwrap();
            assert_eq!(
                json!([actual.line, actual.character]),
                *expected,
                "{id}: {offset}"
            );
        }
    }
    for offset in case["invalid_utf8_offsets"].as_array().unwrap() {
        assert!(
            tree.position(offset.as_u64().unwrap() as usize).is_err(),
            "{id}"
        );
    }
}

fn compatibility(tree: &Parsed, case: &Value) {
    let id = case["id"].as_str().unwrap();
    let elements = tree.elements();
    let source = tree.source();
    let top_level_candidate = |start| {
        elements.iter().any(|e| {
            !e.token
                && e.kind == "FUN"
                && (e.start, e.end) == (start, source.len())
                && e.parent.is_some_and(|p| elements[p].kind == "KT_FILE")
        })
    };
    match case["invariant"].as_str().unwrap() {
        "no-complete-top-level-candidate-fun" => {
            assert!(!tree.diagnostics().is_empty(), "{id}");
            assert!(
                !top_level_candidate(case["candidate_start"].as_u64().unwrap() as usize),
                "{id}"
            );
        }
        "class-end-greater-than-11"
        | "scratch-declines-without-LPAR"
        | "scratch-window-declines; downstream resource result is not promoted to accepted CST" => {
            assert!(!tree.diagnostics().is_empty(), "{id}");
            let class = elements
                .iter()
                .find(|e| !e.token && e.kind == "CLASS")
                .unwrap();
            assert_eq!(class.start, 0, "{id}");
            assert!(class.end > 11, "{id}");
            assert!(!top_level_candidate(source.find("fun").unwrap()), "{id}");
        }
        "aggregate-reset" => {
            assert!(!tree.diagnostics().is_empty(), "{id}");
            let class = elements
                .iter()
                .find(|e| !e.token && e.kind == "CLASS")
                .unwrap();
            assert!(
                class.end > case["declined_start"].as_u64().unwrap() as usize,
                "{id}"
            );
            assert!(
                !top_level_candidate(case["declined_start"].as_u64().unwrap() as usize),
                "{id}"
            );
            assert!(
                top_level_candidate(case["healthy_start"].as_u64().unwrap() as usize),
                "{id}"
            );
        }
        "recovered-boundary-and-downstream-malformed-diagnostics" => {
            for (kind, start, end) in [
                ("CLASS", 0, 11),
                ("TYPE_PARAMETER_LIST", 9, 11),
                ("TYPE_PARAMETER", 10, 11),
            ] {
                assert!(
                    elements
                        .iter()
                        .any(|e| !e.token && e.kind == kind && (e.start, e.end) == (start, end)),
                    "{id}"
                );
            }
            assert!(top_level_candidate(12), "{id}");
            assert!(
                tree.diagnostics()
                    .iter()
                    .any(|d| (d.start, d.end, d.message.as_str()) == (11, 11, "Missing '>'")),
                "{id}"
            );
            assert!(
                tree.diagnostics()
                    .iter()
                    .any(|d| d.message != "Missing '>'"),
                "{id}"
            );
        }
        "object-no-classifier-recovery" => {
            assert!(!tree.diagnostics().is_empty(), "{id}");
            assert!(
                elements.iter().any(|e| !e.token
                    && e.kind == "OBJECT_DECLARATION"
                    && e.start == 0
                    && e.parent.is_some_and(|p| elements[p].kind == "KT_FILE")),
                "{id}"
            );
        }
        "no-classifier-recovery-ownership; anonymous expression remains PROPERTY/BLOCK owned" => {
            let start = source.find("fun a.").unwrap();
            let (anonymous_id, anonymous) = elements
                .iter()
                .enumerate()
                .find(|(_, e)| !e.token && e.kind == "FUN" && e.start == start)
                .unwrap();
            let property = &elements[anonymous.parent.unwrap()];
            assert_eq!(property.kind, "PROPERTY", "{id}");
            assert_eq!(elements[property.parent.unwrap()].kind, "BLOCK", "{id}");
            assert!(
                !elements
                    .iter()
                    .any(|e| e.token && e.kind == "IDENTIFIER" && e.parent == Some(anonymous_id)),
                "{id}"
            );
        }
        other => panic!("unknown frozen invariant: {other}"),
    }
}

#[test]
fn frozen_long_qualified_receiver_contract_through_production_snapshot_worker() {
    let fixtures: Value = serde_json::from_str(FIXTURES).unwrap();
    let positives = fixtures["positive"].as_array().unwrap();
    let controls = fixtures["controls"].as_array().unwrap();
    let resources = fixtures["resource_errors"].as_array().unwrap();
    assert_eq!(
        (positives.len(), controls.len(), resources.len()),
        (64, 50, 2)
    );
    assert_eq!(
        positives
            .iter()
            .map(|c| c["positions"].as_object().unwrap().len())
            .sum::<usize>(),
        1666
    );
    let parser = Parser::new(env!("CARGO_BIN_EXE_ktlsp-parser-worker")).unwrap();
    for case in positives.iter().chain(controls).chain(resources) {
        let id = case["id"].as_str().unwrap();
        let source = case["source"].as_str().unwrap();
        assert_eq!(
            source.len(),
            case["bytes"].as_u64().unwrap() as usize,
            "{id}"
        );
        let snapshot = SourceSnapshot::new(id, 1, FileKind::Source, source).unwrap();
        // Resource failures have no accepted result; retain a prior snapshot through the failed request.
        let prior = if case.get("expected_error").is_some() {
            let healthy =
                SourceSnapshot::new(id, 0, FileKind::Source, "fun healthy() = 2").unwrap();
            Some(
                parser
                    .parse_snapshot(&healthy, &AtomicBool::new(false))
                    .unwrap(),
            )
        } else {
            None
        };
        let result = parser.parse_snapshot(&snapshot, &AtomicBool::new(false));
        let accepted = if case.get("expected_error").is_some() {
            assert_eq!(case["expected_error"], "ParserError::NestingLimit");
            assert_eq!(result.unwrap_err(), ParserError::NestingLimit, "{id}");
            prior.unwrap()
        } else {
            let accepted = result.unwrap_or_else(|error| panic!("{id}: {error:?}"));
            assert_eq!(accepted.snapshot(), &snapshot);
            let tree = accepted.tree_for(&snapshot).unwrap();
            assert_eq!(tree.source(), source);
            let mut cursor = 0;
            let mut reconstructed = String::new();
            for e in tree.elements().iter().filter(|e| e.token) {
                assert_eq!(e.start, cursor, "{id}");
                assert!(
                    source.is_char_boundary(e.start) && source.is_char_boundary(e.end),
                    "{id}"
                );
                reconstructed.push_str(&source[e.start..e.end]);
                cursor = e.end;
            }
            assert_eq!(cursor, source.len(), "{id}");
            assert_eq!(reconstructed, source, "{id}");
            if case.get("projection").is_some() {
                positive(tree, case);
            } else {
                compatibility(tree, case);
            }
            accepted
        };
        let original = accepted.snapshot().clone();
        let tree = accepted.tree_for(&original).unwrap();
        let original_elements = serde_json::to_value(tree.elements()).unwrap();
        let original_diagnostics = serde_json::to_value(tree.diagnostics()).unwrap();
        for mismatch in [
            SourceSnapshot::new(
                format!("{id}-other"),
                original.revision(),
                FileKind::Source,
                original.source(),
            )
            .unwrap(),
            SourceSnapshot::new(
                id,
                original.revision(),
                FileKind::Source,
                format!("{} ", original.source()),
            )
            .unwrap(),
            SourceSnapshot::new(id, original.revision(), FileKind::Script, original.source())
                .unwrap(),
        ] {
            assert_eq!(
                accepted.tree_for(&mismatch).unwrap_err(),
                ParserError::StaleSnapshot,
                "{id}"
            );
        }
        let healthy = SourceSnapshot::new(id, 2, FileKind::Source, "fun healthy() = 2").unwrap();
        assert_eq!(
            accepted.tree_for(&healthy).unwrap_err(),
            ParserError::StaleSnapshot,
            "{id}"
        );
        let followup = parser
            .parse_snapshot(&healthy, &AtomicBool::new(false))
            .unwrap();
        assert_eq!(followup.snapshot(), &healthy);
        let next = followup.tree_for(&healthy).unwrap();
        assert_eq!(next.source(), healthy.source());
        assert_eq!(
            projection(next),
            fixtures["healthy_followup"]["projection"],
            "{id}"
        );
        assert_eq!(
            names(next),
            fixtures["healthy_followup"]["declaration_names"],
            "{id}"
        );
        assert!(next.diagnostics().is_empty(), "{id}");
        assert_eq!(accepted.snapshot(), &original);
        assert_eq!(
            serde_json::to_value(accepted.tree_for(&original).unwrap().elements()).unwrap(),
            original_elements,
            "{id}"
        );
        assert_eq!(
            serde_json::to_value(accepted.tree_for(&original).unwrap().diagnostics()).unwrap(),
            original_diagnostics,
            "{id}"
        );
        assert_eq!(
            accepted.tree_for(&original).unwrap().source(),
            original.source(),
            "{id}"
        );
    }
}

